    DATABASE_URL  = "postgres://recommendations:recommendations@${module.postgres.address}/postgres?sslmode=disable"
    KAFKA_BROKERS = module.kafka.address
    REDIS_ADDR    = module.redis.address
    CATALOG_URL   = app.catalog.url
  }
}

