    AWS_ACCESS_KEY_ID     = "larder"
    AWS_SECRET_ACCESS_KEY = "larder"
    AWS_DEFAULT_REGION    = "eu-west-2"
  }
}

# "Goes well with": co-purchases counted from orders.placed, cached in Redis.
